import os

# Check the session log files
sessions_dir = "/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-6/play/users/u063/system/state/sessions"
print("Session directory contents:")
for item in os.listdir(sessions_dir):
